def number_to_words(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool) or not 0 <= n <= 999999:
        raise ValueError("n must be an integer between 0 and 999999")

    ones = [
        "zero", "one", "two", "three", "four",
        "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen",
    ]
    tens = [
        "", "", "twenty", "thirty", "forty",
        "fifty", "sixty", "seventy", "eighty", "ninety",
    ]

    def under_one_thousand(value: int) -> str:
        parts = []

        if value >= 100:
            parts.append(ones[value // 100])
            parts.append("hundred")
            value %= 100

        if value >= 20:
            word = tens[value // 10]
            if value % 10:
                word += "-" + ones[value % 10]
            parts.append(word)
        elif value > 0:
            parts.append(ones[value])

        return " ".join(parts)

    if n == 0:
        return "zero"

    parts = []
    thousands, remainder = divmod(n, 1000)

    if thousands:
        parts.append(under_one_thousand(thousands))
        parts.append("thousand")

    if remainder:
        parts.append(under_one_thousand(remainder))

    return " ".join(parts)
